func route(_ input: AsyncStream<Envelope>,
           to routes: [RouteKey: AsyncStream<Envelope>.Continuation]) async {
    for await envelope in input {            // AsyncSequence consumption
        switch envelope {                    // exhaustive over the enum
        case .orderCreated: routes[.payment]?.yield(envelope)
        case .orderShipped: routes[.fulfilment]?.yield(envelope)
        }
    }
}
